mrvi_kernel_fit <- function(counts,meta,contrasts,working,rank=10L,hidden=128L,steps=1000L,batch_size=1024L,seed=20260829L,python=Sys.getenv("REGIFT_COMPARATOR_PYTHON", "python"),script=.comparator_script("mrvi_kernel.py")) {
 stopifnot(requireNamespace("RcppCNPy",quietly=TRUE),file.exists(script)); work<-tempfile("mrvi_",tmpdir=tempdir()); dir.create(work,recursive=TRUE); on.exit(unlink(work,recursive=TRUE,force=TRUE),add=TRUE); f<-file.path(work,c("counts.npy","mu0.npy","phi.npy","meta.csv")); RcppCNPy::npySave(f[1],as.matrix(counts)); RcppCNPy::npySave(f[2],as.matrix(working$mu0)); RcppCNPy::npySave(f[3],as.numeric(working$phi)); write.csv(meta,f[4],row.names=FALSE); out<-file.path(work,"out"); args<-c(script,"--counts",f[1],"--meta",f[4],"--mu0",f[2],"--phi",f[3],"--clip",working$clip,"--conditions",paste(colnames(contrasts),collapse=","),"--outdir",out,"--rank",rank,"--hidden",hidden,"--steps",steps,"--batch-size",batch_size,"--seed",seed); status<-system2(python,args = shQuote(as.character(args))); if(!identical(status,0L)) stop("MrVI kernel failed with status ",status); response<-lapply(seq_len(nrow(contrasts)),function(q) RcppCNPy::npyLoad(file.path(out,paste0("response_",q,".npy")))); names(response)<-rownames(contrasts); list(population_response=response,u=RcppCNPy::npyLoad(file.path(out,"u.npy")),diagnostics=jsonlite::fromJSON(file.path(out,"diagnostics.json")),extraction="in-house MrVI hierarchical u/z NB core with sample counterfactual decoding")
}
